var Rows = 26;
var Tile = 24;
var Width = 768;
var Height = 624;
var TPS = 60;
var ActorSize = 44;
var body = (X = 0, Y = 0) => ({
  X,
  Y,
  VX: 0,
  VY: 0,
  Ground: false
});
var powers = () => ({
  Pink: false,
  Blue: false,
  Yellow: false,
  Shoes: false,
  Crystal: false,
  Amethyst: false,
  Ruby: false,
  WalkPoints: 0
});
var position = (c, size) => [
  Math.min(c.col * Tile, Width - 2 * Tile - size),
  Math.max(Tile, c.row * Tile - size)
];

// src/arcade/balance.ts
var productionPlayerBalance = Object.freeze({
  MoveSpeed: 2.5,
  ShoesSpeed: 3.5,
  BubbleSpeed: 6,
  BlueBubbleSpeed: 9,
  BubbleRange: 160,
  PinkBubbleRange: 240,
  FireCooldown: 24,
  YellowFireCooldown: 12
});
var referencePlayerBalance = Object.freeze({
  MoveSpeed: 3,
  ShoesSpeed: 5,
  BubbleSpeed: 8,
  BlueBubbleSpeed: 16,
  BubbleRange: 200,
  PinkBubbleRange: 400,
  FireCooldown: 18,
  YellowFireCooldown: 5
});

// src/arcade/physics.ts
function solid(g2, col, row) {
  if (col < 2 || col >= 30) return true;
  if (row < 0 || row >= Rows) return false;
  return g2.Level.tiles[row][col] !== 0;
}
function blocked(g2, x, y, size) {
  for (let row = Math.floor(y / Tile); row <= Math.floor((y + size - 0.01) / Tile); row++)
    for (let col = Math.floor(x / Tile); col <= Math.floor((x + size - 0.01) / Tile); col++)
      if (solid(g2, col, row)) return true;
  return false;
}
function spawnPosition(g2, c) {
  const [x, y] = position(c, ActorSize);
  if (!blocked(g2, x, y, ActorSize)) return [x, y];
  let best = Number.MAX_VALUE, bx = x, by = y;
  for (let row = 1; row < Rows - 2; row++)
    for (let col = 2; col < 29; col++) {
      const xx = col * Tile, yy = row * Tile, d = Math.abs(xx - x) + Math.abs(yy - y);
      if (d < best && !blocked(g2, xx, yy, ActorSize)) {
        best = d;
        bx = xx;
        by = yy;
      }
    }
  return [bx, by];
}
function advanceActor(g2, b, dx, gravity, firstLandingRow = 0) {
  const inside = blocked(g2, b.X + 2, b.Y + 2, ActorSize - 4), steps = Math.max(1, Math.ceil(Math.abs(dx)));
  for (let i = 0; i < steps; i++) {
    const x = Math.max(
      2 * Tile,
      Math.min(Width - 2 * Tile - ActorSize, b.X + dx / steps)
    );
    if (b.VY >= 0 && !inside && blocked(g2, x + 2, b.Y + 2, ActorSize - 4))
      break;
    b.X = x;
  }
  if (gravity) b.VY = Math.min(12, b.VY + 0.5);
  const oldFeet = b.Y + ActorSize;
  let newY = b.Y + b.VY;
  b.Ground = false;
  if (b.VY >= 0) {
    for (let row = Math.max(firstLandingRow, Math.ceil(oldFeet / Tile)); row <= Math.floor((newY + ActorSize) / Tile); row++) {
      for (let col = Math.trunc((b.X + 4) / Tile); col <= Math.trunc((b.X + ActorSize - 4) / Tile); col++) {
        if (solid(g2, col, row)) {
          newY = row * Tile - ActorSize;
          b.VY = 0;
          b.Ground = true;
          break;
        }
      }
      if (b.Ground) break;
    }
  }
  b.Y = newY;
}
function wrapBottom(b) {
  if (b.Y > Height) {
    b.Y = Tile;
    b.VY = 2;
  }
}
function matchingVerticalOpening(g2, b) {
  const first = Math.floor(b.X / Tile), last = Math.floor((b.X + ActorSize - 0.01) / Tile);
  for (let col = first; col <= last; col++)
    if (solid(g2, col, 0) || solid(g2, col, Rows - 1)) return false;
  return true;
}
function movePlayer(g2, b, dx) {
  advanceActor(g2, b, dx, true, 1);
  if (b.VY < 0 && b.Y + ActorSize < 0 && matchingVerticalOpening(g2, b))
    b.Y += Height + ActorSize;
  wrapBottom(b);
}

