// src/arcade/bubbles.ts
var bubble = (X = 0, Y = 0) => ({
  ...body(X, Y),
  ID: 0,
  Dir: 0,
  Age: 0,
  EnemyID: 0,
  CapturedAge: 0,
  Distance: 0,
  MaxDistance: 0,
  Speed: 0,
  Floating: false,
  Removed: false,
  Element: ""
});
function shootBubble(g2, player) {
  const p2 = g2.Players[player], balance = g2.PlayerBalance ?? productionPlayerBalance, speed = p2.Power.Blue ? balance.BlueBubbleSpeed : balance.BubbleSpeed, reach = p2.Power.Pink ? balance.PinkBubbleRange : balance.BubbleRange;
  g2.NextID++;
  g2.Bubbles.push({
    ...bubble(p2.X + p2.Dir * 18, p2.Y + 2),
    ID: g2.NextID,
    Shooter: player,
    Dir: p2.Dir,
    Speed: speed,
    MaxDistance: reach
  });
  g2.Counters.Blown++;
  if (p2.Power.Ruby) addScore(g2, 100, p2.X, p2.Y);
  g2.Sounds.push("shoot");
}

// src/arcade/player.ts
function respawn(g2, index) {
  const c = { ...g2.Level.player };
  if (index === 1) c.col = 28 - c.col;
  const [x, y] = spawnPosition(g2, c), lives = g2.Players[index].Lives;
  g2.Players[index] = {
    ...body(x, y),
    Lives: lives,
    Dir: 1 - index * 2,
    Invincible: 210,
    JumpBuffer: 0,
    Coyote: 0,
    LastJump: false,
    Dead: 0,
    Shoot: 0,
    Cooldown: 0,
    WalkFrame: 0,
    Power: powers()
  };
}
function updatePlayer(g2, index, input) {
  const p2 = g2.Players[index], i = { ...input }, balance = g2.PlayerBalance ?? productionPlayerBalance;
  if (p2.Invincible > 0) p2.Invincible--;
  if (p2.Shoot > 0) p2.Shoot--;
  if (p2.Cooldown > 0) p2.Cooldown--;
  if (i.Jump && !p2.LastJump) p2.JumpBuffer = 8;
  p2.LastJump = i.Jump;
  if (p2.JumpBuffer > 0) p2.JumpBuffer--;
  if (p2.Ground) p2.Coyote = 6;
  else if (p2.Coyote > 0) p2.Coyote--;
  if (p2.JumpBuffer > 0 && p2.Coyote > 0) {
    p2.VY = -11.5;
    p2.Ground = false;
    p2.Coyote = 0;
    p2.JumpBuffer = 0;
    g2.Counters.Jumps++;
    if (p2.Power.Amethyst) addScore(g2, 500, p2.X, p2.Y);
    g2.Sounds.push("jump");
  }
  const speed = p2.Power.Shoes ? balance.ShoesSpeed : balance.MoveSpeed;
  i.Move = Math.max(-1, Math.min(1, i.Move));
  if (i.Move !== 0) {
    p2.Dir = i.Move;
    p2.WalkFrame++;
  }
  const oldX = p2.X;
  movePlayer(g2, p2, i.Move * speed);
  const distance = Math.abs(p2.X - oldX);
  g2.Counters.Walked += distance;
  if (p2.Power.Crystal) {
    p2.Power.WalkPoints += distance;
    while (p2.Power.WalkPoints >= 8) {
      addScore(g2, 10, p2.X, p2.Y);
      p2.Power.WalkPoints -= 8;
    }
  }
  if (i.Fire && p2.Cooldown === 0) {
    shootBubble(g2, index);
    p2.Cooldown = p2.Power.Yellow ? balance.YellowFireCooldown : balance.FireCooldown;
    p2.Shoot = 12;
  }
}

// src/arcade/rng.ts
var mask = (1n << 64n) - 1n;
var multiplier = 2549297995355413924n << 64n | 4865540595714422341n;
var increment = 6364136223846793005n << 64n | 1442695040888963407n;
function createRNG(seed) {
  const s = BigInt(seed) & mask;
  return { RNG: "7063673a" + s.toString(16).padStart(16, "0") + (s ^ 0xa0761d6478bd642fn).toString(16).padStart(16, "0") };
}
function uint64(rng) {
  if (!/^7063673a[0-9a-f]{32}$/.test(rng.RNG)) throw new Error("invalid PCG encoding");
  const state = BigInt.asUintN(128, BigInt("0x" + rng.RNG.slice(8)) * multiplier + increment);
  rng.RNG = "7063673a" + state.toString(16).padStart(32, "0");
  let hi = state >> 64n;
  const lo = state & mask;
  hi = BigInt.asUintN(64, (hi ^ hi >> 32n) * 0xda942042e4dd58b5n);
  return BigInt.asUintN(64, (hi ^ hi >> 48n) * (lo | 1n));
}
function float64(rng) {
  return Number(uint64(rng) & (1n << 53n) - 1n) / 9007199254740992;
}
function intN(rng, n) {
  if (!Number.isSafeInteger(n) || n <= 0) throw new Error("invalid argument to IntN");
  const bound = BigInt(n);
  if ((bound & bound - 1n) === 0n) return Number(uint64(rng) & bound - 1n);
  let product = uint64(rng) * bound;
  const threshold = (1n << 64n) % bound;
  while ((product & mask) < threshold) product = uint64(rng) * bound;
  return Number(product >> 64n);
}

// src/arcade/game.ts
function createGame(levels, seed, count = 1) {
  if (count < 1 || count > 2) throw new Error("expected one or two players");
  if (!levels.length) throw new Error("no levels supplied");
  for (const level of levels) validateLevel(level);
  const g2 = {
    PlayerBalance: { ...productionPlayerBalance },
    NormalEnemySpeedScale: 0.8,
    Campaign: levels,
    Level: levels[0],
    LevelIndex: 0,
    Custom: false,
    State: 0 /* Ready */,
    Paused: false,
    Tick: 0,
    LevelTicks: 0,
    Countdown: 0,
    Freeze: 0,
    Hurry: false,
    Score: 0,
    Players: Array.from({ length: count }, () => ({
      ...body(),
      Lives: 3,
      JumpBuffer: 0,
      Coyote: 0,
      LastJump: false,
      Dir: 0,
      Invincible: 0,
      Dead: 0,
      Shoot: 0,
      Cooldown: 0,
      WalkFrame: 0,
      Power: powers()
    })),
    Enemies: [],
    Bubbles: [],
    Projectiles: [],
    Items: [],
    Effects: [],
    Particles: [],
    Sounds: [],
    Counters: {
      Blown: 0,
      Popped: 0,
      Jumps: 0,
      Water: 0,
      Thunder: 0,
      Fire: 0,
      Pink: 0,
      Blue: 0,
      Yellow: 0,
      Walked: 0
    },
    WaterStage: 0,
    Pending: [],
    SpawnedSpecial: 0,
    NextID: 0,
    ExtraLifeAt: 3e4,
    RNG: createRNG(seed).RNG
  };
  loadLevel(g2, 0);
  return g2;
}
function loadLevel(g2, index) {
  if (index >= g2.Campaign.length) {
    g2.State = 4 /* Won */;
    g2.Sounds.push("opening");
    return;
  }
  g2.LevelIndex = index;
  g2.Level = {
    ...g2.Campaign[index],
    tiles: g2.Campaign[index].tiles.map((row) => row.slice()),
    enemies: g2.Campaign[index].enemies.map((e) => ({ ...e })),
    player: { ...g2.Campaign[index].player },
    power_spawn: { ...g2.Campaign[index].power_spawn },
    food_spawn: { ...g2.Campaign[index].food_spawn }
  };
  g2.LevelTicks = 0;
  g2.Freeze = 0;
  g2.SpawnedSpecial = 0;
  g2.Hurry = false;
  g2.Paused = false;
  g2.Bubbles = [];
  g2.Projectiles = [];
  g2.Items = [];
  g2.Effects = [];
  g2.Particles = [];
  g2.Enemies = [];
  for (const spawn of g2.Level.enemies) {
    const [x, y] = spawnPosition(g2, spawn);
    g2.NextID++;
    const dir = intN(g2, 2) === 0 ? 1 : -1;
    g2.Enemies.push({
      ...body(x, y),
      CarriedBy: 0,
      CarryTicks: 0,
      ID: g2.NextID,
      Kind: spawn.kind,
      State: 0 /* Active */,
      Dir: dir,
      Vertical: 1,
      Angry: false,
      Age: 0,
      Cooldown: 180,
      Shoot: 0,
      DeadTicks: 0,
      Phase: float64(g2) * 2 * Math.PI
    });
  }
  for (let i = 0; i < g2.Players.length; i++) {
    respawn(g2, i);
    g2.Players[i].Invincible = 0;
  }
  g2.State = 0 /* Ready */;
  g2.Countdown = TPS;
}
function addScore(g2, points, x, y) {
  g2.Score += points;
  if (points >= 100)
    g2.Particles.push({ ...body(x, y), Text: String(points), Life: 45 });
  while (g2.Score >= g2.ExtraLifeAt) {
    for (let i = 0; i < g2.Players.length; i++) {
      const p2 = g2.Players[i];
      p2.Lives++;
      if (p2.Lives === 1 && p2.Dead === 0) respawn(g2, i);
    }
    g2.ExtraLifeAt += 1e5;
    g2.Particles.push({
      ...body(g2.Players[0].X, g2.Players[0].Y - 24),
      Text: "1UP",
      Life: 90
    });
  }
}
function validateLevel(l) {
  const fail = (message) => {
    throw new Error(message);
  };
  if (l.number < 1 || l.number > 25)
    fail("tile theme must be between 1 and 25");
  if (l.tiles.length !== 26) fail("expected 26 rows");
  for (const row of l.tiles) {
    if (row.length !== 32) fail("expected 32 columns");
    for (let col = 0; col < 32; col++) {
      if (row[col] < 0 || row[col] > 25) fail("invalid tile");
      if ((col < 2 || col >= 30) && row[col] === 0)
        fail("side walls must remain closed");
    }
  }
  if (!l.enemies.length || l.enemies.length > 32)
    fail("place between 1 and 32 enemies");
  const valid = (c) => c.col >= 2 && c.col < 30 && c.row >= 1 && c.row < 26;
  for (const e of l.enemies) {
    if (!["zenchan", "monsta", "mighta", "pulpul", "banebou", "invader"].includes(
      e.kind
    ))
      fail("unknown enemy");
    if (!valid(e)) fail("enemy is outside the arena");
  }
  if (!valid(l.player) || !valid(l.power_spawn) || !valid(l.food_spawn))
    fail("spawn point is outside the arena");
  if (l.special !== "" && !["water", "thunder", "fire"].includes(l.special))
    fail("unknown special bubble");
  if (l.special_count < 0 || l.special_count > 100)
    fail("invalid special bubble count");
  let space = false;
  for (let row = 1; row < 24; row++)
    for (let col = 2; col < 29; col++)
      if (l.tiles[row][col] === 0 && l.tiles[row][col + 1] === 0 && l.tiles[row + 1][col] === 0 && l.tiles[row + 1][col + 1] === 0)
        space = true;
  if (!space) fail("leave room for the player and enemies");
}

